def is_valid_parenthesization(parentheses):
    current_depth = 0
    for char in parentheses:
        if char == '(':
            current_depth += 1
        elif char == ')':
            current_depth -= 1
            if current_depth < 0:
                return False
    return current_depth == 0
```
