Here is a Python script that can recursively scan PDFs in a directory and rename them based on their content:
```python
import os 
import pdfplumber
import re

def rename_pdfs(dir_path):
    for filename in os.listdir(dir_path):
        path = os.path.join(dir_path, filename)
        if os.path.isdir(path):
            rename_pdfs(path)
        else:
            if path.endswith(".pdf"):
                rename_file(path)

def rename_file(file_path):
    with pdfplumber.PDF(open(file_path, 'rb')) as pdf:
        pages = [page for page in pdf.pages]
        text = []
        for page in pages:
            text.append(page.extract_text())
        text = " ".join(text)

        # Remove non-ASCII characters
        text = re.sub(r'[^A-Za-z0-9 ]+', ' ', text)

        # Remove punctuation, make lowercase and split into words
        text = re.sub(r'[^\w\s]', ' ', text).lower().split() 

        # Count frequency of each word
        word_freqs = {}
        for word in text:
            if word in word_freqs:
                word_freqs[word] += 1
            else:
                word_freqs[word] = 1

        # Get most frequent words
        most_frequent = sorted(word_freqs, key=word_freqs.get, reverse=True)[:5]

        # Construct new filename using most frequent words
        new_name = "_".join(most_frequent) + ".pdf"
        os.rename(file_path, os.path.join(os.path.dirname(file_path), new_name))

if __name__ == "__main__":
    rename_pdfs("/path/to/pdfs") 
```

This script will recursively scan all PDFs in the given directory and subdirectories. For each PDF, it will extract the text, count the word frequencies, get the 5 most frequent words, and construct a new filename using those words. It will then rename the PDF file accordingly.

