def two_sum(arr, target):
    # Create a dictionary to store the numbers as keys and their indices as values
    num_dict = {}
    for i, num in enumerate(arr):
        if num in num_dict:
            num_dict[num][1] = i
        else:
            num_dict[num] = [i, i]

    # Initialize two pointers, one at the beginning and one at the end of the list
    left, right = 0, len(arr) - 1

    # Iterate until the pointers meet
    while left < right:
        current_sum = arr[left] + arr[right]
        if current_sum == target:
            # Check if both numbers are in the dictionary
            if (arr[left], arr[right]) in num_dict[target]:
                return (arr[left], arr[right])
            # Update the pointers
            left += 1
            right -= 1
        elif current_sum < target:
            left += 1
        else:
            right -= 1

    # If the pointers don't meet, there's no solution
