```python
def binary_search(arr, val):
    start = 0
    end = len(arr) - 1

    while start <= end:
        mid = (start + end) // 2
        if arr[mid] == val:
            return mid
        elif val < arr[mid]:
            start = mid + 1
        else:
            end = mid - 1

    return -1

def binary_search_recursive(arr, val, start, end):
    if start > end:
        return -1

    mid = (start + end) // 2
    if arr[mid] == val:
        return mid
    elif val < arr[mid]:
        return binary_search_recursive(arr, val, start, mid)
    else:
        return binary_search_recursive(arr, val, mid + 1, end)

def p1(arr, val):
    return binary_search_recursive(arr, val, 0, len(arr))

def p2(start, end, mid):
    if start > end:
        return -1

    mid = (start + end) // 2
    if start == end:
        return mid
    elif arr[mid] == val:
        return mid
    elif val < arr[mid]:
        return p2(start, mid, mid)
    else:
        return p2(mid + 1, end, mid)

