def lzw_encode(input_string):
    # Step 1: Initialize the dictionary with all single characters in the input string
    dictionary = {}
    for c in input_string:
        if c in dictionary:
            dictionary[c] = dictionary[c] + {c}
        else:
            dictionary[c] = {c}

    # Step 2: Find the longest prefix in the remaining input string that is in the dictionary
    output_list = []
    current_prefix = ''
    for c in input_string:
        if c in dictionary:
            current_prefix += c
            while c in dictionary and dictionary[c] != current_prefix:
                current_prefix = dictionary[c]
            if current_prefix == input_string:
                break
        else:
            break
        output_list.append(dictionary[current_prefix])
        current_prefix = c

    # Step 3: Append the token mapped to the prefix found in step 2
    for c in input_string:
        if c in dictionary:
            output_list.append(dictionary[c])
        else:
            break

    # Step 4: Insert an entry to the dictionary
    for prefix in output_list:
        dictionary[prefix] = dictionary[prefix] + input_string[len(prefix):]

    # Step 5: Return the output list
    return output_list
```

