```python
def p1(arr, x):
    low, high = 0, len(arr) - 1
    return p2(arr, low, high, x)

def p2(arr, low, high, x):
    if low > high:
        return -1

    mid = (low + high) // 2

    if arr[mid] == x:
        return mid

    if arr[mid] < x:
        return p2(arr, low, mid - 1, x)

    return p2(arr, mid + 1, high, x)

# Example usage:
