import os

def get_asset_references(directory):
    references = []
    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.endswith((".png", ".jpg", ".png", ".jpeg", ".gif", ".mp4", ".avi", ".mov", ".wmv", ".flv", ".mp3", ".aac", ".wav", ".flac", ".ogg", ".opus")):
