```python
import heapq
from collections import defaultdict

def get(heap, node):
    idx = heapq.heappop(heap)
    return idx, heapq.heappop(heap)

def insert_or_update(heap, node, distance):
    heapq.heappush(heap, (node, distance))

def shortest_path_length(graph, start_node, destination_node):
    visited = defaultdict(int)
    visited[start_node] = 0

    fibonacci_heap = [(start_node, 0), ]

    while fibonacci_heap:
        _, distance = get(fibonacci_heap, start_node)

        if start_node == destination_node:
            return distance

        for successor_node, successor_distance in graph[start_node]:
            new_distance = distance + successor_distance
            new_node = (successor_node, new_distance)

            if successor_node not in visited or new_distance < visited[successor_node]:
                visited[successor_node] = new_distance
                insert_or_update(fibonacci_heap, successor_node, new_distance)

    return float('inf')

def graph_distance_update(graph, u, v, distance):
    graph[u][v] = distance

def graph_distance_query(graph, u, v):
    return graph[u].get(v, float('inf'))

