    result = binary_string_to_int(binary1) + binary_string_to_int(binary2)
    return binary_to_string(result)

# Subtract one binary number from another
def binary_sub(binary1, binary2):
    result = binary_string_to_int(binary1) - binary_string_to_int(binary2)
    return binary_to_string(result)

# Multiply two binary numbers
