    result = binary_string_to_int(binary1) * binary_string_to_int(binary2)
    return binary_to_string(result)

# Divide one binary number by another
def binary_div(binary1, binary2):
    quotient, remainder = binary_string_to_int(binary1) // binary_string_to_int(binary2)
    return binary_to_string(quotient), binary_to_string(remainder)

# Convert a binary number to its decimal equivalent
