    # Create a dictionary to count the characters in str1
    char_count = {}
    for char in str1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Check if str2 has the same characters and counts as str1
    for char in str2:
        if char in char_count:
            char_count[char] -= 1
            if char_count[char] < 0:
