```python
def lis(arr, n):
    if n == 0:
        return 0

    ends = {}
    longest = 0
    for i in range(n):
        ends[i] = 0
        longest = max(longest, i)

    for val in arr:
        for i in range(n):
            if i < val:
                ends[i] = val
                longest = max(longest, ends[i] + 1)

    return longest

