```python
def lis(arr):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1

    for i in range(1, n):
        dp[i][0] = 0

    for i in range(1, n):
        for j in range(1, n):
            if arr[j] > arr[i]:
                dp[j][i] = dp[j][i-1] + 1
            else:
                dp[j][i] = max(dp[j][i-1], dp[j-1][i-1])

    return dp[-1][-1]

# Test the function with a sample input
